  for (const k of Object.keys(raw)) {
    const make = raw[k]
    out[k] = typeof make === 'function' ? (/** @type {any} */ props = {}) => make(Object.fromEntries(Object.entries(props).filter(([, v]) => v !== undefined))) : make
