export function normalizePaint(paint, toRgb) {
  if (!paint || typeof paint !== 'object') return null
  const list = paint.stops
  if (!Array.isArray(list) || list.length < 2 || list.length > STOPS_MAX) return null
  /** @type {NStop[]} */
