    if (!rgb) return null
    const o = s.opacity === undefined || s.opacity === null ? 1 : s.opacity
    if (!Number.isFinite(o)) return null
    stops.push({ at: clamp01(s.at), rgb: rgb.map(r4), a: clamp01(o) })
