/** @param {NStop} last @returns {NSolid} */
function solid(last) {
  return { kind: 'solid', rgb: last.rgb, alpha: last.a < 1 - 1e-6 ? 'uniform' : 'none', uniform: last.a, key: JSON.stringify(['solid', last.rgb, r4(last.a)]) }
